#requires -version 5.1
$ErrorActionPreference='Stop';$Root=Split-Path -Parent $PSCommandPath;$Main=Join-Path $Root 'RepairCenter.ps1';$Broker=Join-Path $Root 'ElevatedBroker.ps1';$BuildInfoPath=Join-Path $Root 'BuildInfo.psd1';$Log=Join-Path $Root 'Launcher.log'
function Log([string]$Text){try{("[{0}] {1}" -f (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'),$Text)|Add-Content -LiteralPath $Log -Encoding UTF8}catch{}}
function Hash([string]$p){return (Get-FileHash -Algorithm SHA256 -LiteralPath $p -ErrorAction Stop).Hash.ToLowerInvariant()}
function Parse-One([string]$Path){$tokens=$null;$errors=$null;[void][System.Management.Automation.Language.Parser]::ParseFile($Path,[ref]$tokens,[ref]$errors);return @($errors)}
try{if(-not(Test-Path -LiteralPath $BuildInfoPath)){throw "Missing BuildInfo: $BuildInfoPath"};$Build=Import-PowerShellDataFile -LiteralPath $BuildInfoPath;foreach($p in @($Main,$Broker)){if(-not(Test-Path -LiteralPath $p)){throw "Missing runtime file: $p"}};if((Hash $Main) -ne [string]$Build.EngineSHA256){throw 'Engine SHA256 mismatch vs BuildInfo'};if((Hash $Broker) -ne [string]$Build.BrokerSHA256){throw 'Broker SHA256 mismatch vs BuildInfo'};if((Hash $PSCommandPath) -ne [string]$Build.BootstrapSHA256){throw 'Bootstrap SHA256 mismatch vs BuildInfo'};$all=@();foreach($p in @($Main,$Broker)){foreach($e in @(Parse-One $p)){$all += ("{0} Line {1}, Col {2}: {3}" -f [IO.Path]::GetFileName($p),$e.Extent.StartLineNumber,$e.Extent.StartColumnNumber,$e.Message)}};if($all.Count -gt 0){$detail=$all -join "`r`n";Log("Parser errors: "+$detail);Add-Type -AssemblyName System.Windows.Forms;[System.Windows.Forms.MessageBox]::Show(("v{0} PowerShell 5.1 语法检查失败，未执行任何修复。`r`n`r`n{1}`r`n`r`n日志：{2}" -f $Build.Version,$detail,$Log),("Windows Game Runtime / ASUS Self-Healing Center v"+$Build.Version),[System.Windows.Forms.MessageBoxButtons]::OK,[System.Windows.Forms.MessageBoxIcon]::Error)|Out-Null;exit 100};Log ("Integrity + Parser check PASS; Version="+$Build.Version+" Build="+$Build.BuildId);& $Main;Log 'Engine exited normally.'}catch{Log("FATAL: "+$_.Exception.Message);try{Add-Type -AssemblyName System.Windows.Forms;$v='unknown';try{$v=[string](Import-PowerShellDataFile -LiteralPath $BuildInfoPath).Version}catch{};[System.Windows.Forms.MessageBox]::Show(("v{0} 启动失败：`r`n{1}`r`n`r`n日志：{2}" -f $v,$_.Exception.Message,$Log),("Windows Game Runtime / ASUS Self-Healing Center v"+$v),[System.Windows.Forms.MessageBoxButtons]::OK,[System.Windows.Forms.MessageBoxIcon]::Error)|Out-Null}catch{};exit 101}
